@@ -0,0 +1,208 @@
+import { dirname, basename, join } from "node:path";
+import { rename } from "node:fs/promises";
+
+type Status = "open" | "done";
+
+interface Task {
+  id: number;
+  title: string;
+  status: Status;
+  tags: string[];
+  createdAt: string;
+  due?: string;
+  completedAt?: string;
+}
+
+interface Database {
+  nextId: number;
+  tasks: Task[];
+}
+
+const databasePath = process.env.TASKBOARD_FILE || join(process.cwd(), ".taskboard.json");
+
+function fail(message: string): never {
+  throw new Error(message);
+}
+
+function isDate(value: string): boolean {
+  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
+  if (!match) return false;
+  const year = Number(match[1]);
+  const month = Number(match[2]);
+  const day = Number(match[3]);
+  const date = new Date(Date.UTC(year, month - 1, day));
+  return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day;
+}
+
+function normalizeTag(tag: string): string {
+  return tag.trim().toLowerCase();
+}
+
+function parseId(value: string | undefined): number {
+  if (!value || !/^[1-9]\d*$/.test(value)) fail("ID must be a positive integer");
+  return Number(value);
+}
+
+function validateDatabase(value: unknown): asserts value is Database {
+  if (!value || typeof value !== "object") fail("Malformed taskboard database");
+  const db = value as Record<string, unknown>;
+  if (!Number.isSafeInteger(db.nextId) || (db.nextId as number) < 1 || !Array.isArray(db.tasks)) {
+    fail("Malformed taskboard database");
+  }
+  const ids = new Set<number>();
+  for (const value of db.tasks) {
+    if (!value || typeof value !== "object") fail("Malformed taskboard database");
+    const task = value as Record<string, unknown>;
+    if (
+      !Number.isSafeInteger(task.id) || (task.id as number) < 1 || ids.has(task.id as number) ||
+      typeof task.title !== "string" || task.title.trim() === "" ||
+      (task.status !== "open" && task.status !== "done") ||
+      !Array.isArray(task.tags) || !task.tags.every((tag) => typeof tag === "string") ||
+      typeof task.createdAt !== "string" || Number.isNaN(Date.parse(task.createdAt)) ||
+      (task.due !== undefined && (typeof task.due !== "string" || !isDate(task.due))) ||
+      (task.completedAt !== undefined && (typeof task.completedAt !== "string" || Number.isNaN(Date.parse(task.completedAt))))
+    ) fail("Malformed taskboard database");
+    ids.add(task.id as number);
+  }
+  if ([...ids].some((id) => id >= (db.nextId as number))) fail("Malformed taskboard database");
+}
+
+async function loadDatabase(): Promise<Database> {
+  const file = Bun.file(databasePath);
+  if (!(await file.exists())) return { nextId: 1, tasks: [] };
+  let value: unknown;
+  try {
+    value = await file.json();
+  } catch {
+    fail("Malformed taskboard database");
+  }
+  validateDatabase(value);
+  return value;
+}
+
+async function saveDatabase(database: Database): Promise<void> {
+  const temporary = join(
+    dirname(databasePath),
+    `.${basename(databasePath)}.${process.pid}.${crypto.randomUUID()}.tmp`,
+  );
+  try {
+    await Bun.write(temporary, `${JSON.stringify(database, null, 2)}\n`);
+    await rename(temporary, databasePath);
+  } catch (error) {
+    try { await Bun.file(temporary).delete(); } catch {}
+    throw error;
+  }
+}
+
+function options(args: string[], allowed: Set<string>): Map<string, string> {
+  const result = new Map<string, string>();
+  for (let index = 0; index < args.length; index += 2) {
+    const flag = args[index];
+    const value = args[index + 1];
+    if (!flag?.startsWith("--") || !allowed.has(flag)) fail(`Unknown flag: ${flag ?? ""}`);
+    if (value === undefined || value.startsWith("--")) fail(`Missing value for ${flag}`);
+    if (result.has(flag)) fail(`Duplicate flag: ${flag}`);
+    result.set(flag, value);
+  }
+  return result;
+}
+
+function localToday(): string {
+  const now = new Date();
+  const year = now.getFullYear();
+  const month = String(now.getMonth() + 1).padStart(2, "0");
+  const day = String(now.getDate()).padStart(2, "0");
+  return `${year}-${month}-${day}`;
+}
+
+async function main(args: string[]): Promise<unknown> {
+  const [command, ...rest] = args;
+  if (!command) fail("Missing command");
+  const database = await loadDatabase();
+
+  if (command === "add") {
+    const parsed = options(rest, new Set(["--title", "--tags", "--due"]));
+    const title = parsed.get("--title")?.trim();
+    if (!title) fail("A non-empty --title is required");
+    const due = parsed.get("--due");
+    if (due !== undefined && !isDate(due)) fail("Due date must be a valid YYYY-MM-DD date");
+    const rawTags = parsed.get("--tags");
+    const tags = rawTags === undefined
+      ? []
+      : [...new Set(rawTags.split(",").map(normalizeTag).filter(Boolean))];
+    const task: Task = {
+      id: database.nextId++,
+      title,
+      status: "open",
+      tags,
+      createdAt: new Date().toISOString(),
+      ...(due === undefined ? {} : { due }),
+    };
+    database.tasks.push(task);
+    await saveDatabase(database);
+    return task;
+  }
+
+  if (command === "list") {
+    const parsed = options(rest, new Set(["--status", "--tag", "--overdue"]));
+    const status = parsed.get("--status");
+    if (status !== undefined && status !== "open" && status !== "done") {
+      fail("Status must be open or done");
+    }
+    const tag = parsed.has("--tag") ? normalizeTag(parsed.get("--tag")!) : undefined;
+    if (tag === "") fail("Tag must not be empty");
+    const overdue = parsed.get("--overdue");
+    if (overdue !== undefined && !isDate(overdue)) fail("Overdue date must be a valid YYYY-MM-DD date");
+    return database.tasks
+      .filter((task) => status === undefined || task.status === status)
+      .filter((task) => tag === undefined || task.tags.includes(tag))
+      .filter((task) => overdue === undefined || (task.status === "open" && task.due !== undefined && task.due < overdue))
+      .sort((a, b) => a.id - b.id);
+  }
+
+  if (command === "done") {
+    if (rest.length !== 1) fail("Usage: done ID");
+    const id = parseId(rest[0]);
+    const task = database.tasks.find((candidate) => candidate.id === id);
+    if (!task) fail(`Task ${id} not found`);
+    if (task.status === "open") {
+      task.status = "done";
+      task.completedAt = new Date().toISOString();
+      await saveDatabase(database);
+    }
+    return task;
+  }
+
+  if (command === "delete") {
+    if (rest.length !== 1) fail("Usage: delete ID");
+    const id = parseId(rest[0]);
+    const index = database.tasks.findIndex((task) => task.id === id);
+    if (index === -1) fail(`Task ${id} not found`);
+    const [task] = database.tasks.splice(index, 1);
+    await saveDatabase(database);
+    return task;
+  }
+
+  if (command === "stats") {
+    if (rest.length !== 0) fail("Usage: stats");
+    const today = localToday();
+    return {
+      total: database.tasks.length,
+      open: database.tasks.filter((task) => task.status === "open").length,
+      done: database.tasks.filter((task) => task.status === "done").length,
+      overdue: database.tasks.filter((task) => task.status === "open" && task.due !== undefined && task.due < today).length,
+    };
+  }
+
+  fail(`Unknown command: ${command}`);
+}
+
+try {
+  const result = await main(Bun.argv.slice(2));
+  console.log(JSON.stringify(result));
+} catch (error) {
+  const message = error instanceof Error ? error.message : String(error);
+  console.error(message);
+  console.log(JSON.stringify({ error: message }));
+  process.exitCode = 1;
+}

