import { afterEach, describe, expect, test } from "bun:test";
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

const cli = join(import.meta.dir, "..", "src", "cli.ts");
const directories: string[] = [];

async function workspace(): Promise<{ directory: string; database: string }> {
  const directory = await mkdtemp(join(tmpdir(), "taskboard-"));
  directories.push(directory);
  return { directory, database: join(directory, "tasks.json") };
}

function run(directory: string, database: string, ...args: string[]) {
  const result = Bun.spawnSync(["bun", "run", cli, ...args], {
    cwd: directory,
    env: { ...process.env, TASKBOARD_FILE: database },
    stdout: "pipe",
    stderr: "pipe",
  });
  const stdout = result.stdout.toString().trim();
  return {
    exitCode: result.exitCode,
    stdout,
    stderr: result.stderr.toString().trim(),
    json: JSON.parse(stdout),
  };
}

afterEach(async () => {
  await Promise.all(directories.splice(0).map((directory) => rm(directory, { recursive: true, force: true })));
});

describe("taskboard CLI", () => {
  test("persists tasks, normalizes tags, and keeps IDs stable", async () => {
    const { directory, database } = await workspace();
    const first = run(directory, database, "add", "--title", " First task ", "--tags", "Work, work,URGENT", "--due", "2020-02-29");
    const second = run(directory, database, "add", "--title", "Second task");

    expect(first.exitCode).toBe(0);
    expect(first.stderr).toBe("");
    expect(first.json).toMatchObject({ id: 1, title: "First task", status: "open", tags: ["work", "urgent"], due: "2020-02-29" });
    expect(new Date(first.json.createdAt).toISOString()).toBe(first.json.createdAt);
    expect(second.json.id).toBe(2);
    expect(run(directory, database, "delete", "1").json.id).toBe(1);
    expect(run(directory, database, "add", "--title", "Third task").json.id).toBe(3);
    expect(run(directory, database, "list").json.map((task: { id: number }) => task.id)).toEqual([2, 3]);
  });

  test("combines list filters and treats overdue as open-only", async () => {
    const { directory, database } = await workspace();
    run(directory, database, "add", "--title", "Old", "--tags", "Team", "--due", "2020-01-01");
    run(directory, database, "add", "--title", "Later", "--tags", "team", "--due", "2030-01-01");
    run(directory, database, "add", "--title", "Other", "--tags", "other", "--due", "2020-01-01");
    run(directory, database, "done", "1");

    expect(run(directory, database, "list", "--status", "open", "--tag", "TEAM").json.map((task: { id: number }) => task.id)).toEqual([2]);
    expect(run(directory, database, "list", "--overdue", "2025-01-01").json.map((task: { id: number }) => task.id)).toEqual([3]);
  });

  test("done is idempotent and stats reflect persisted state", async () => {
    const { directory, database } = await workspace();
    run(directory, database, "add", "--title", "Old", "--due", "2000-01-01");
    run(directory, database, "add", "--title", "Current");
    const done = run(directory, database, "done", "2").json;
    const repeated = run(directory, database, "done", "2").json;

    expect(repeated.completedAt).toBe(done.completedAt);
    expect(run(directory, database, "stats").json).toEqual({ total: 2, open: 1, done: 1, overdue: 1 });
  });

  test("rejects invalid input without corrupting the database", async () => {
    const { directory, database } = await workspace();
    run(directory, database, "add", "--title", "Keep me");
    const before = await readFile(database, "utf8");
    const failures = [
      ["add", "--title", "   "],
      ["add", "--title", "Bad date", "--due", "2023-02-29"],
      ["list", "--status", "waiting"],
      ["list", "--unknown", "value"],
      ["done", "999"],
      ["unknown"],
    ];

    for (const args of failures) {
      const result = run(directory, database, ...args);
      expect(result.exitCode).not.toBe(0);
      expect(result.stderr.length).toBeGreaterThan(0);
      expect(result.json).toHaveProperty("error");
      expect(result.stdout.split("\n")).toHaveLength(1);
    }
    expect(await readFile(database, "utf8")).toBe(before);
  });

  test("fails safely on malformed storage", async () => {
    const { directory, database } = await workspace();
    await writeFile(database, "not json\n");
    const result = run(directory, database, "list");

    expect(result.exitCode).not.toBe(0);
    expect(result.stderr).toContain("Malformed taskboard database");
    expect(await readFile(database, "utf8")).toBe("not json\n");
  });
});

